import('./src/index.js').then(async ({ createGate }) => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const assert = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); process.exit(1); } };

  // 1. Reparent a ROOT gate (with a child) under another root.
  const root1 = createGate({ limit: 3, windowMs: 1000 });
  const child = createGate({ limit: 2, windowMs: 1000, parent: root1 });
  await root1.acquire(1);          // root1 pool: 1 used (its own)
  await child.acquire(2);          // root1 pool: 3 used (2 via child)
  const root2 = createGate({ limit: 6, windowMs: 60 });
  root1.reparent(root2);           // whole family moves; draw = 3
  // old root1 state is now a child; root2 pool carries 3
  let refused = false;
  try { await root2.acquire(4); } catch (e) { refused = e.code === 'QUOTA_EXCEEDED'; }
  assert(refused, 'root2 pool should carry the moved draw (3 of 6)');
  const h = await root2.acquire(3); // exactly fits
  h.release();
  // root1's own window stats unchanged shape
  assert(root1.stats().inFlight === 1, 'root1 inFlight preserved');
  assert(child.stats().inFlight === 2, 'child inFlight preserved');
  // after root2's flip, pool resets for the moved family too
