  h2.release();
  console.log('root reparent ok');

  // 2. Borrow reclaim follows the gate to the new family.
  const p1 = createGate({ limit: 5, windowMs: 60 });
  const c = createGate({ limit: 2, windowMs: 10000, parent: p1 });
  await c.acquire(2);              // own
  await c.acquire(2);              // borrowed 2
  const p2 = createGate({ limit: 8, windowMs: 60 });
  c.reparent(p2);                  // borrowedInFlight travels along
  assert(c.stats().inFlight === 4, 'inFlight intact right after reparent');
  await sleep(90);                 // p2's window flips: reclaim happens there
  assert(c.stats().inFlight === 2, 'borrow reclaimed at the NEW family flip, got ' + c.stats().inFlight);
  console.log('borrow reclaim after reparent ok');

  // 3. Expiry outranks a same-moment cancellation.
  const g = createGate({ limit: 1, windowMs: 1000, maxWaitMs: 30 });
  await g.acquire(1);
  const ctl = new AbortController();
  const p = g.acquire(1, { signal: ctl.signal }).then((h) => h, (e) => e);
  await sleep(50);                 // deadline passed, expiry timer fired
  ctl.abort();
  const err = await p;
  assert(err.code === 'WAIT_EXPIRED', 'expiry wins over late cancel');
  assert(g.stats().expired === 1 && g.stats().cancelled === 0, 'counters');
  console.log('expiry-over-cancel ok');
}).catch((e) => { console.error(e); process.exit(1); });
"
